//! Shared helper functions for common card resolution patterns.
//!
//! Includes:
//! - Spell resolution helpers (resolve_aura, resolve_damage, resolve_destroy)
//! - Choice presentation helpers (present_target_choice, present_yes_no, etc.)
//! - Target collection helpers (any_targets, creature_targets, etc.)

use crate::actions::Target;
use crate::cards::CardRegistry;
use crate::events::{DamageTarget, GameEvent};
use crate::ids::{ObjectId, PlayerId};
use crate::state::{AwaitingAction, GameState, LogLevel, PendingEffect, ResolutionChoiceKind};
use crate::types::Zone;

/// Resolve an aura spell: attach it to the target creature on the battlefield.
/// If the target is no longer on the battlefield, the aura goes to graveyard.
/// Returns true if the aura was successfully attached.
pub fn resolve_aura(state: &mut GameState, aura_id: ObjectId, targets: &[Target]) -> bool {
    if let Some(Target::Object(target_id)) = targets.first() {
        if state.get_object(*target_id).map(|o| o.zone == Zone::Battlefield).unwrap_or(false) {
            state.move_object(aura_id, Zone::Battlefield);
            if let Some(obj) = state.get_object_mut(aura_id) {
                obj.attached_to = Some(*target_id);
                obj.summoning_sick = false;
            }
            return true;
        }
    }
    state.move_spell_after_resolve(aura_id);
    false
}

/// Resolve a curse aura: attach to a target player and move to battlefield.
pub fn resolve_curse(state: &mut GameState, curse_id: ObjectId, targets: &[Target]) -> bool {
    if let Some(Target::Player(player_id)) = targets.first() {
        state.move_object(curse_id, Zone::Battlefield);
        if let Some(obj) = state.get_object_mut(curse_id) {
            obj.attached_to_player = Some(*player_id);
            obj.summoning_sick = false;
        }
        return true;
    }
    state.move_spell_after_resolve(curse_id);
    false
}

/// Resolve a damage spell: deal `amount` damage to the first target
/// (creature or player), then move the spell to the appropriate zone.
pub fn resolve_damage(state: &mut GameState, spell_id: ObjectId, targets: &[Target], amount: u32) {
    if let Some(target) = targets.first() {
        match target {
            Target::Object(target_id) => {
                if let Some(obj) = state.get_object_mut(*target_id) {
                    if obj.zone == Zone::Battlefield {
                        obj.damage_marked += amount;
                        obj.damaged_by.push(spell_id);
                        state.events.push(GameEvent::NonCombatDamageDealt {
                            source: spell_id,
                            target: DamageTarget::Object(*target_id),
                            amount,
                        });
                    }
                }
            }
            Target::Player(player_id) => {
                let old_life = state.get_player(*player_id).life;
                let new_life = old_life - (amount as i32);
                state.get_player_mut(*player_id).life = new_life;
                state.events.push(GameEvent::NonCombatDamageDealt {
                    source: spell_id,
                    target: DamageTarget::Player(*player_id),
                    amount,
                });
                state.events.push(GameEvent::LifeChanged {
                    player: *player_id,
                    old: old_life,
                    new_life,
                });
            }
        }

pub fn eligible_attackers(state: &GameState, player: PlayerId, registry: &CardRegistry) -> Vec<ObjectId> {
    state.objects.values()
        .filter(|o| {
            o.zone == Zone::Battlefield
                && o.controller == player
                && o.power.is_some()
                && !o.tapped
                // Haste overrides summoning sickness.
                && (!o.summoning_sick || state.has_keyword(o.id, Keyword::Haste, registry))
                // Defender can't attack.
                && !state.has_keyword(o.id, Keyword::Defender, registry)
                // Check aura-based restrictions (Pacifism).
                && state.can_attack(o.id, registry)
        })
        .map(|o| o.id)
        .collect()
}

/// Get all creatures a player controls that are eligible to block.
/// Checks continuous effects (Pacifism, can't block, etc.).
pub fn eligible_blockers(state: &GameState, player: PlayerId, registry: &CardRegistry) -> Vec<ObjectId> {
    state.objects.values()
        .filter(|o| {
            o.zone == Zone::Battlefield
                && o.controller == player
                && o.power.is_some()
                && !o.tapped
        })
        .map(|o| o.id)
        .collect::<Vec<_>>()
        .into_iter()
        .filter(|&id| state.can_block(id, registry))
        // "Can't block" (e.g., Vampire Interloper) — check continuous effects.
        .filter(|&id| {
            !state.has_continuous_effect(id, &|e| {
                match e {
                    crate::types::ContinuousEffect::PreventBlock { scope } => Some(scope),
                    _ => None,
                }
            }, registry)
        })
        // "Can't block this turn" (e.g., Nightbird's Clutches).
        .filter(|&id| !state.until_end_of_turn_cant_block.contains(&id))
        .collect()
}

